class Solution {
public:
    int maxTastiness(vector<int>& price, vector<int>& tastiness, int maxAmount, int maxCoupons) {
        vector<vector<int>> dp(maxCoupons + 1, vector<int>(maxAmount + 1, 0));
        for (int i = 0; i < (int)price.size(); ++i) {
            for (int coupon = maxCoupons; coupon >= 0; --coupon) {
                for (int money = maxAmount; money >= 0; --money) {
                    if (money >= price[i])
                        dp[coupon][money] = max(dp[coupon][money], dp[coupon][money - price[i]] + tastiness[i]);
                    if (coupon > 0 && money >= price[i] / 2)
                        dp[coupon][money] = max(dp[coupon][money], dp[coupon - 1][money - price[i] / 2] + tastiness[i]);
                }
            }
        }
        return dp[maxCoupons][maxAmount];
    }
};
